    void decodingFinished(QString kind,bool success,QString message,quint64 request=0){
        if(!waiting_||kind!=waitingKind_)return;
        if(batchTotal_){if(request){if(!batchRequests_.remove(request))return;}else{if(batchWindow_!=1||batchRequests_.isEmpty())return;batchRequests_.erase(batchRequests_.begin());}batchInFlight_=batchRequests_.size();waiting_=batchInFlight_>0;
            if(!success){++batchFailed_;if(batchErrors_.size()<20)batchErrors_.append(message);if(message.contains("canceled",Qt::CaseInsensitive)||message.contains("changed",Qt::CaseInsensitive)||message.contains("memory budget",Qt::CaseInsensitive)){pendingPreviews_.clear();batchStopped_=true;}}else{++batchDone_;if(message.contains("[Texture warning]"))++batchTextureWarnings_;}
            updateBatchProgress();if(pendingPreviews_.isEmpty()&&!batchInFlight_){finishBatch();return;}QTimer::singleShot(0,this,[this]{startNextPreview();});selectionChanged();return;
        }
        if(request)return;waiting_=false;status_->setText((success?"Preview loaded: ":"Decoding failed: ")+message);selectionChanged();
    }
