private:
    bool batchActive_=false;
    // Scanner sweep over the document bytes when the Hex Viewer is showing; otherwise over this panel's results area.
    void startSweep(){if(sweepOn_)return;sweepOn_=true;sweepOnHex_=view_&&view_->isVisible();if(sweepOnHex_)view_->setScanAnimation(true);else{if(!sweep_)sweep_=new ScanSweepOverlay(tree_->viewport());sweep_->start();}}
    void stopSweep(){if(!sweepOn_)return;sweepOn_=false;if(sweepOnHex_)view_->setScanAnimation(false);else if(sweep_)sweep_->stop();}
    void setBatchActive(bool active){if(batchActive_==active)return;batchActive_=active;batchStop_->setVisible(active);if(active){batchClock_.start();updateBatchProgress();progress_->show();}else if(!watcher_.isRunning()&&!resourceWatcher_.isRunning())progress_->hide();if(batchStateChanged)batchStateChanged(active);}
    QFutureWatcher<NativeResources::Output> resourceWatcher_;quint64 resourceGeneration_=0;QJsonObject resourceRow_,resourceOrigin_;
    void extractSelected(){
        if(resourceWatcher_.isRunning()||watcher_.isRunning()||!openResource)return;auto origin=view_->property("nativeResourceOrigin").toJsonObject();int depth=origin["depth"].toInt();if(depth>=NativeResources::MaxDepth){status_->setText("Nested resource depth limit reached (4). Save a resource separately to continue manually.");return;}resourceRow_=selected()["data"].toObject();resourceOrigin_=origin;resourceOrigin_["depth"]=depth+1;auto chain=origin["chain"].toArray();chain.append(QJsonObject{{"source",view_->filePath().isEmpty()?"RAM document":view_->filePath()},{"sourceSize",QString::number(view_->fileSize())},{"sourceModified",view_->meshSource().expectedModified.toString(Qt::ISODateWithMs)},{"includedPendingEdits",view_->dirty()},{"entry",resourceRow_}});resourceOrigin_["chain"]=chain;resourceGeneration_=generation_;cancel_=std::make_shared<std::atomic_bool>(false);auto cancel=cancel_;auto source=view_->meshSource();auto patches=view_->pendingPatches();auto row=resourceRow_;waiting_=true;selectionChanged();progress_->setRange(0,0);progress_->setFormat("Opening resource...");progress_->show();startSweep();stop_->setEnabled(true);status_->setText("Reading / decompressing the selected resource locally...");resourceWatcher_.setFuture(QtConcurrent::run([source,patches,row,cancel]{return NativeResources::extract(source,patches,row,*cancel);}));
    }
    QLineEdit *filter_;
    void filterResults(){filterAssetTree(tree_,filter_->text());selectionChanged();}
    void updateOptionsSummary(){optionsToggle_->setText(mode_=="image"?QString("Scan options"):QString("Scan options  \u00b7  ")+(trackContext_.isEmpty()?"textures automatic":"textures manual: "+trackContext_["profile"].toObject()["variant"].toString()));}
    void updateBatchProgress(){if(!batchTotal_)return;const int processed=batchDone_+batchSkipped_+batchFailed_;progress_->setRange(0,batchTotal_);progress_->setValue(qMin(processed,batchTotal_));QString text=QString("%1 / %2").arg(processed).arg(batchTotal_);const double seconds=batchClock_.isValid()?batchClock_.elapsed()/1000.0:0;if(processed>0&&seconds>0.5){const double rate=processed/seconds;const int eta=int((batchTotal_-processed)/rate+0.5);text+=QString("  \u00b7  %1/s  \u00b7  ETA %2:%3").arg(rate,0,'f',rate<10?1:0).arg(eta/60).arg(eta%60,2,10,QChar('0'));}if(batchFailed_)text+=QString("  \u00b7  %1 failed").arg(batchFailed_);progress_->setFormat(text);}
    void finishBatch(){status_->setText(QString("%1: %2 loaded, %3 already loaded, %4 failed, %5 omitted. Texture warnings: %6.").arg(batchStopped_?"Batch stopped":"Render complete").arg(batchDone_).arg(batchSkipped_).arg(batchFailed_).arg(batchOmitted_).arg(batchTextureWarnings_));if(!batchErrors_.isEmpty())details_->setPlainText(batchErrors_.join('\n'));updateBatchProgress();batchTotal_=0;waiting_=false;batchInFlight_=0;batchRequests_.clear();setBatchActive(false);selectionChanged();}
    void startNextPreview(){if(!batchTotal_||!valid_||!useCandidate)return;
        if(!batchInFlight_&&batchDone_+batchSkipped_+batchFailed_==0){batchStopped_=false;batchRequests_.clear();batchWindow_=2;for(const auto &row:pendingPreviews_)if(row["kind"]!="mesh"||row["data"].toObject()["profileId"]!="native-pgr34-track"){batchWindow_=1;break;}}
        QElapsedTimer slice;slice.start();while(!pendingPreviews_.isEmpty()&&batchInFlight_<batchWindow_&&slice.elapsed()<8){auto row=pendingPreviews_.takeFirst();auto data=row["data"].toObject();static quint64 nextRequest=1;auto request=nextRequest++;data["_scanRequest"]=qint64(request);auto result=useCandidate(row["kind"].toString(),data,true);if(result["skipped"].toBool()){++batchSkipped_;continue;}if(!result["started"].toBool()){++batchFailed_;if(batchErrors_.size()<20)batchErrors_.append(result["error"].toString("Could not start preview."));pendingPreviews_.clear();batchStopped_=true;break;}batchRequests_.insert(request);batchInFlight_=batchRequests_.size();waiting_=true;waitingKind_=row["kind"]=="image"?"image":"mesh";}
        updateBatchProgress();if(pendingPreviews_.isEmpty()&&!batchInFlight_)finishBatch();else{status_->setText(QString("Loading %1 / %2 (%3 in flight)...").arg(batchDone_+batchSkipped_+batchFailed_).arg(batchTotal_).arg(batchInFlight_));if(!pendingPreviews_.isEmpty()&&batchInFlight_<batchWindow_)QTimer::singleShot(0,this,[this]{startNextPreview();});selectionChanged();}}
